            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Et pour sa voix, lointaine, et calme, et grave, elle a L'inflexion des voix chères qui se sont tues.", Author = "Paul Verlaine" },
