            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Les sanglots longs Des violons De l'automne Blessent mon cœur D'une langueur Monotone.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Et je m'en vais Au vent mauvais Qui m'emporte Deçà, delà Pareil à la Feuille morte.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Votre âme est un paysage choisi Que vont charmants masques et bergamasques Jouant du luth et dansant et quasi Tristes sous leurs déguisements fantasques.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Colombine rêve, surprise De sentir un cœur dans la brise Et d’entendre en son cœur des voix.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Fardée et peinte comme au temps des bergeries, Frêle parmi les nœuds énormes de rubans, Elle passe, sous les ramures assombries, Dans l’allée où verdit la mousse des vieux bancs", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Trompeurs exquis et coquettes charmantes, Cœurs tendres mais affranchis du serment, Nous devisons délicieusement", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Le soir tombait, un soir équivoque d’automne : Les belles, se pendant rêveuses à nos bras, Dirent alors des mots si spécieux, tout bas, Que notre âme depuis ce temps tremble et s’étonne.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Ce fut le temps, sous de clairs ciels, (Vous en souvenez-vous, Madame ?) Des baisers superficiels Et des sentiments à fleur d’âme", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Heureux instants ! — mais vint l’Été : Adieu, rafraîchissantes brises ! Un vent de lourde volupté Investit nos âmes surprises.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Scaramouche et Pulcinella Qu’un mauvais dessein rassembla Gesticulent, noirs sur la lune.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Un pavillon à claires-voies Abride doucement nos joies", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Et l’Amour comblant tout, hormis La faim, sorbets et confitures Nous préservent des courbatures.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Cependant la lune se lève Et l’esquif en sa course brève File gaîment sur l’eau qui rêve.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Cléopâtre fut moins aimée, oui, sur ma foi ! Par Marc-Antoine et par César que vous par moi, N’en doutez pas, Madame, et je saurai combattre Comme César pour un sourire, ô Cléopâtre, Et comme Antoine fuir au seul prix d’un baiser.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Ferme tes yeux à demi, Croise tes bras sur ton sein, Et de ton cœur endormi Chasse à jamais tout dessein.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "— Ton cœur bat-il toujours à mon seul nom ? Toujours vois-tu mon âme en rêve ? — Non.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Il pleure dans mon cœur Comme il pleut sur la ville, Quelle est cette langueur Qui pénètre mon cœur ?", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Le ciel est, par-dessus le toit, Si bleu, si calme ! Un arbre, par-dessus le toit Berce sa palme.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Je ne sais pourquoi Mon esprit amer D'une aile inquiète et folle vole sur la mer. Tout ce qui m'est cher, D'une aile d'effroi Mon amour le couve au ras des flots. Pourquoi, pourquoi ?", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "On sait trop tout le prix du malheur Pour le perdre en disert gaspillage. Vous n'aurez ni mes traits ni mon âge, Ni le vrai mal secret de mon cœur.", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Le bonheur de saigner sur le cœur d'un ami, Le besoin de pleurer bien longtemps sur son sein, Le désir de parler à lui, bas à demi, Le rêve de rester ensemble sans dessein !", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Mortel, ange et démon, autant dire Rimbaud, Tu mérites la prime place en ce mien livre", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "À l’Escrime, le seul de nos maîtres sortable, Robert, nous démontrait quelque coup inouï D’audace magnifique ou de ruse admirable Et nous clamions à plein gosier : Ça c’est de Lui !", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Une inquiétude profonde M'agite en douloureux transports Entre le sublime et l'immonde : – Deux écueils, Seigneur, ou deux ports ?", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Je compare ces vers étranges Aux étranges vers que ferait Un marquis de Sade discret Qui saurait la langue des anges", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Quand même tu dirais Que tu me trahirais Si c'était ton caprice, Qu’est-ce que me ferait Ce terrible secret Si c’était mon caprice !", Author = "Paul Verlaine" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Verlaine", Text = "Dans ce café bondé d'imbéciles, nous deux Seuls, nous représentions le soi-disant hideux Vice d'être « pour homme » et sans qu'ils s'en doutassent Nous encagnions ces cons avec leur air bonasse, Leurs normales amours et leur morale en toc.", Author = "Paul Verlaine" },
